pub fn rib_a(buf: &[u8], pos: u32, n: u32) -> u32 {
    if n == 0 {
        return 0;
    }
    if n > 32 {
        return 0;
    }
    let end = match pos.checked_add(n) {
        Some(v) => v as usize,
        None => return 0,
    };
    if end > buf.len().saturating_mul(8) {
        return 0;
    }

    let mut value = 0u32;
    for p in pos as usize..end {
        let bit = (buf[p / 8] >> (7 - (p % 8))) & 1;
        value = (value << 1) | bit as u32;
    }
    value
}
